const today='2026-09-24';
const exercise={id:'barbell-hip-thrust',name:'Barbell hip thrust',group:'Glutes',equipment:'Barbell',restSeconds:180,tracking:'weight_reps'};
const makeCard=(id:string,name:string)=>({id,name,notes:'Four working sets, controlled technique.',items:[{exercise,targetSets:4,targetReps:'6–10'}],created_at:today,updated_at:today,program_day:1,program_activated_at:'2026-09-20T00:00:00Z',archived:false});
export const db:any={workout_cards:[makeCard('card-a','Glutes + Hamstrings'),makeCard('card-b','Chest + Delts + Triceps')],workout_calendar:[{id:'today',scheduled_on:today,card_id:'card-b',kind:'workout',status:'planned',moved_to:null},{id:'missed',scheduled_on:'2026-09-21',card_id:'card-a',kind:'workout',status:'planned',moved_to:null}],workouts:[],workout_templates:[],active_workout_drafts:[],workout_exercises:[]};
(globalThis as any).testDB=db;
export const supabase:any={auth:{getUser:async()=>({data:{user:{id:'test-user'}}})},rpc:async(name:string,args:any={})=>{
 if(name==='ensure_workout_cards')return{data:null,error:null};
 if(name==='plan_workout_recurrence'){let first:any;for(let i=0;i<(args.p_count||1);i++){const d=new Date(args.p_date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+i*7*(args.p_interval_weeks||1));const date=d.toISOString().slice(0,10);let e=db.workout_calendar.find((x:any)=>x.scheduled_on===date);if(i&&e)continue;if(!e){e={id:crypto.randomUUID(),scheduled_on:date};db.workout_calendar.push(e)}Object.assign(e,{card_id:args.p_card,kind:args.p_card?'workout':'rest',status:'planned',moved_to:null});if(!i)first=e.id}return{data:first,error:null}}
 if(name==='move_workout_day'){const e=db.workout_calendar.find((x:any)=>x.id===args.p_id);db.workout_calendar.push({...e,id:crypto.randomUUID(),scheduled_on:args.p_date});e.status='moved';e.moved_to=args.p_date;return{error:null}}
 if(name==='save_workout_draft'){db.active_workout_drafts=[{user_id:'test-user',session:args.p_session}];return{error:null}}
 if(name==='finish_workout_session'){const s=args.p_session;if(!db.workouts.some((x:any)=>x.id===s.id))db.workouts.push({id:s.id,name:s.name,started_at:s.startedAt,completed_at:new Date().toISOString(),workout_exercises:[]});if(s.calendarEntryId)db.workout_calendar.find((x:any)=>x.id===s.calendarEntryId).status='completed';db.active_workout_drafts=[];return{data:s.id,error:null}}
 throw Error('Unexpected RPC '+name)
},from(table:string){let filters:Array<(r:any)=>boolean>=[],single=false,mutation='',payload:any;const chain:any={select(){return chain},eq(k:string,v:any){filters.push(r=>r[k]===v);return chain},neq(k:string,v:any){filters.push(r=>r[k]!==v);return chain},gte(k:string,v:any){filters.push(r=>r[k]>=v);return chain},lte(k:string,v:any){filters.push(r=>r[k]<=v);return chain},not(){return chain},order(){return chain},limit(){return chain},maybeSingle(){single=true;return chain},update(p:any){mutation='update';payload=p;return chain},delete(){mutation='delete';return chain},upsert(p:any){mutation='upsert';payload=p;return chain},then(resolve:any,reject:any){return Promise.resolve().then(()=>{const rows=db[table]||[],matches=rows.filter((r:any)=>filters.every(f=>f(r)));if(mutation==='update')matches.forEach((r:any)=>Object.assign(r,payload));if(mutation==='delete')db[table]=rows.filter((r:any)=>!matches.includes(r));if(mutation==='upsert'){const old=rows.find((r:any)=>r.id===payload.id);if(old)Object.assign(old,payload);else rows.push({...payload,created_at:today})}return{data:single?matches[0]||null:matches,error:null}}).then(resolve,reject)}};return chain}};
